package com.tekwatt.telemetry.dto;import com.tekwatt.telemetry.entity.TelemetryReading;import java.math.BigDecimal;import java.time.Instant;import java.util.UUID;public record TelemetryResponse(UUID id,UUID tenantId,UUID chargerId,UUID connectorId,UUID sessionId,String transactionId,String measurand,BigDecimal value,String unit,String phase,String context,String location,Instant sampledAt,Instant receivedAt){public static TelemetryResponse from(TelemetryReading r){return new TelemetryResponse(r.getId(),r.getTenantId(),r.getChargerId(),r.getConnectorId(),r.getSessionId(),r.getTransactionId(),r.getMeasurand(),r.getValue(),r.getUnit(),r.getPhase(),r.getContext(),r.getLocation(),r.getSampledAt(),r.getReceivedAt());}}
